public class CosmicCats {
    private final Set<Integer> catIdentifiers;

    public CosmicCats(Set<Integer> catIds) {
        this.catIdentifiers = Collections.unmodifiableSet(new HashSet<>(catIds));
    }

    public boolean isCosmicCat(int identifier) {
