import java.util.*;

public class CosmicCats {
    private Set<String> cats;

    public CosmicCats(Set<String> cats) {
        this.cats = Collections.unmodifiableSet(new HashSet<>(cats));
    }

    public boolean isCat(String identifier) {
        return cats.contains(identifier);
    }

    @Override
    public String toString() {
        return "Cosmic Cats: " + Arrays.toString(cats.toArray());
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Set<String> cats = new HashSet<>();
        cats.add("Whiskers");
        cats.add("Paws");
        cats.add("Claw");

        CosmicCats cosmicCats = new CosmicCats(cats);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Future<Boolean> future1 = executor.submit(() -> cosmicCats.isCat("Whiskers"));
        Future<Boolean> future2 = executor.submit(() -> cosmicCats.isCat("Paws"));

        boolean result1 = future1.get();
        boolean result2 = future2.get();

        System.out.println(result1); // true
        System.out.println(result2); // false

        executor.shutdownNow();
    }
}

