import java.util.*;

/**
* ThreeStooges
*
* A truly immutable class using an unmodifiable set,
* suitable for safe concurrent access and model checking with JPF.
*/
public final class ThreeStooges {
private final Set<String> stooges;

public ThreeStooges() {
Set<String> temp = new HashSet<>();
temp.add("Moe");
temp.add("Larry");
temp.add("Curly");
this.stooges = Collections.unmodifiableSet(temp);
}

public boolean isStooge(String name) {
return stooges.contains(name);
}

public String getStoogeNames() {
// This method returns a string representation of the stooge names
return new ArrayList<>(stooges).toString();
}

public static void main(String[] args) throws InterruptedException {
ThreeStooges threeStooges = new ThreeStooges();

Thread t1 = new Thread(() -> {
String[] names = {"Moe", "Larry", "Curly", "Shemp"};
for (String name : names) {
boolean result = threeStooges.isStooge(name);
System.out.println("Thread-1: isStooge(" + name + ") = " + result);
}
System.out.println("Thread-1: Stooge names: " + threeStooges.getStoogeNames());
});

Thread t2 = new Thread(() -> {
String[] names = {"Moe", "Larry", "Curly", "Shemp"};
for (String name : names) {
boolean result = threeStooges.isStooge(name);
System.out.println("Thread-2: isStooge(" + name + ") = " + result);
}
System.out.println("Thread-2: Stooge names: " + threeStooges.getStoogeNames());
});

t1.start();
t2.start();

t1.join();
t2.join();

System.out.println("All threads have finished execution.");
}
}

