import java.util.concurrent.locks.*;
import java.util.concurrent.TimeUnit;

public class DeadlockAvoidance {
    private static final int DEFAULT_TIMEOUT = 100; // milliseconds
    private static final int DEFAULT_PAUSE = 50; // milliseconds

    public static void main(String[] args) throws NotEnoughItemsException, InterruptedException {
        Locker sourceLocker = new Locker();
        Locker targetLocker = new Locker();

        ParcelCount parcelCount = new ParcelCount();
        Lock sourceLock = new ReentrantLock();
        Lock targetLock = new ReentrantLock();

        // Thread 1: move parcels from source to target locker
        Runnable task1 = () -> {
            try {
                while (true) {
                    int quantityToMove = parcelCount.getAvailableQuantity();
                    if (quantityToMove == 0) break;

                    Lock sourceLockerLock = null;
                    Lock targetLockerLock = null;

                    try {
                        // Acquire locks with timeout and random pause
                        sourceLockerLock = acquireLock(sourceLock, DEFAULT_TIMEOUT, DEFAULT_PAUSE);
                        targetLockerLock = acquireLock(targetLock, DEFAULT_TIMEOUT, DEFAULT_PAUSE);

                        // Move parcels between lockers
                        parcelCount.moveParcels(quantityToMove, sourceLocker, targetLocker);
                    } finally {
                        // Release locks if acquired
                        releaseLock(sourceLockerLock);
                        releaseLock(targetLockerLock);
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Thread 2: simulate parcel arrival and availability
        Runnable task2 = () -> {
            try {
                while (true) {
                    if (parcelCount.getAvailableQuantity() == 0) {
                        // Simulate parcel arrival
                        int newParcels = ThreadLocalRandom.current().nextInt(1, 5);
                        parcelCount.addParcels(newParcels);
                    } else {
                        // Simulate parcel consumption
                        int consumedParcels = ThreadLocalRandom.current().nextInt(1, Math.min(parcelCount.getAvailableQuantity(), 5));
                        parcelCount.consumeParcels(consumedParcels);
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Start threads
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(task1);
        executor.submit(task2);
    }

    private static Lock acquireLock(ReentrantLock lock, int timeout, int pause) throws InterruptedException {
        long startTime = System.currentTimeMillis();
        while (true) {
            if (lock.tryLock()) {
                return lock;
            } else {
                // Calculate random delay component
                int randomDelay = ThreadLocalRandom.current().nextInt(pause);
                // Sleep for a random delay before retrying
                TimeUnit.MILLISECONDS.sleep(randomDelay);
                // Check if timeout has elapsed
                long currentTime = System.currentTimeMillis();
                if (currentTime - startTime > timeout) {
                    return null;
                }
            }
        }
    }

    private static void releaseLock(Lock lock) {
        if (lock != null && lock.isHeldByCurrentThread()) {
            lock.unlock();
        }
    }

    // Nested classes
    public static class ParcelCount {
        private int availableQuantity;

        public void addParcels(int newParcels) {
            availableQuantity += newParcels;
        }

        public void consumeParcels(int consumedParcels) {
            availableQuantity -= consumedParcels;
        }

        public int getAvailableQuantity() {
            return availableQuantity;
        }
    }

    public static class Locker {
        // Implementation omitted for brevity
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

public class DeadlockAvoidance {
    private static ReentrantLock sourceLocker = new ReentrantLock();
    private static ReentrantLock targetLocker = new ReentrantLock();
    private static ParcelCount parcelCount = new ParcelCount(10);

    public static void main(String[] args) throws InterruptedException {
        Thread moveThread = new Thread(() -> {
            try {
                move(sourceLocker, targetLocker, 5, 10, TimeUnit.SECONDS);
            } catch (NotEnoughItemsException e) {
                System.out.println("Move failed: " + e.getMessage());
            }
        });

        moveThread.start();
        moveThread.join(20000); // wait for 20 seconds
    }

    private static void move(ReentrantLock sourceLocker, ReentrantLock targetLocker, int quantityToMove, long timeout, TimeUnit unit) throws NotEnoughItemsException {
        if (!sourceLocker.isLocked() && !targetLocker.isLocked()) {
            throw new NotEnoughItemsException("Source locker is not locked");
        }

        try {
            if (sourceLocker.tryLock(timeout, unit)) {
                try {
                    if (!targetLocker.isLocked() && parcelCount.getParcelCount() >= quantityToMove) {
                        System.out.println("Moving " + quantityToMove + " parcels from source locker to target locker");
                        parcelCount.decrement(quantityToMove);
                    } else {
                        throw new NotEnoughItemsException("Target locker is not locked or there are not enough items in the source locker");
                    }
                } finally {
                    sourceLocker.unlock();
                }
            } else {
                System.out.println("Failed to acquire source locker lock within " + timeout + " " + unit);
            }
        } catch (InterruptedException e) {
            System.out.println("Move interrupted: " + e.getMessage());
            Thread.currentThread().interrupt();
        }
    }

    private static class ParcelCount {
        private int parcelCount;

        public ParcelCount(int initialParcelCount) {
            this.parcelCount = initialParcelCount;
        }

        public void increment() {
            synchronized (this) {
                parcelCount++;
            }
        }

        public int getParcelCount() {
            return parcelCount;
        }

        public void decrement(int quantityToMove) {
            synchronized (this) {
                if (parcelCount >= quantityToMove) {
                    parcelCount -= quantityToMove;
                } else {
                    throw new NotEnoughItemsException("There are not enough items in the source locker");
                }
            }
        }
    }

    private static class Locker {
        private int id;
        private ReentrantLock lock;

        public Locker(int id) {
            this.id = id;
            lock = new ReentrantLock();
        }

        public int getId() {
            return id;
        }

        public boolean isLocked() {
            return lock.isLocked();
        }
    }
}

import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class Locker {
    private static final int MAX_PARCELS = 10;
    private int parcelCount;
    private ReentrantLock lock;

    public Locker() {
        this.parcelCount = 0;
        this.lock = new ReentrantLock();
    }

    public void addParcels(int count) {
        if (count <= MAX_PARCELS - parcelCount) {
            parcelCount += count;
        } else {
            throw new IllegalArgumentException("Cannot add more than " + MAX_PARCELS + " parcels");
        }
    }

    public int getParcelCount() {
        return parcelCount;
    }

    public boolean moveParcels(Locker target, int count) throws InterruptedException {
        lock.lock();
        try {
            if (parcelCount < count) {
                throw new NotEnoughItemsException("Source locker has insufficient items");
            } else {
                parcelCount -= count;
                target.addParcels(count);
                return true;
            }
        } finally {
            lock.unlock();
        }
    }
}

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

public class Main {
    private static final int NUM_LOCKERS = 2;
    private static final int TIMEOUT = 1000; // milliseconds
    private static final TimeUnit TIME_UNIT = TimeUnit.MILLISECONDS;

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_LOCKERS);
        Locker[] lockers = new Locker[NUM_LOCKERS];
        for (int i = 0; i < NUM_LOCKERS; i++) {
            lockers[i] = new Locker();
        }

        executor.submit(new ParcelMover(lockers, TIMEOUT, TIME_UNIT));
    }
}

class ParcelMover implements Runnable {
    private final Locker[] lockers;
    private final int timeout;
    private final TimeUnit timeUnit;

    public ParcelMover(Locker[] lockers, int timeout, TimeUnit timeUnit) {
        this.lockers = lockers;
        this.timeout = timeout;
        this.timeUnit = timeUnit;
    }

    @Override
    public void run() {
        try {
            boolean moved = moveParcels(lockers, 5);
            if (moved) {
                System.out.println("Moved 5 parcels from locker 1 to locker 2");
            } else {
                System.out.println("Failed to move parcels");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public boolean moveParcels(Locker[] lockers, int count) throws InterruptedException {
        Locker source = lockers[0];
        Locker target = lockers[1];

        ReentrantLock sourceLock = source.getLock();
        ReentrantLock targetLock = target.getLock();

        boolean success = false;
        int attempts = 0;

        while (!success && attempts < 3) {
            try {
                if (sourceLock.tryLock(timeout, timeUnit)) {
                    try {
                        if (targetLock.tryLock(timeout, timeUnit)) {
                            try {
                                int sourceCount = source.getParcelCount();
                                int targetCount = target.getParcelCount();

                                if (sourceCount >= count) {
                                    source.addParcels(-count);
                                    target.addParcels(count);
                                    success = true;
                                } else {
                                    throw new NotEnoughItemsException("Source locker has insufficient items");
                                }
                            } finally {
                                targetLock.unlock();
                            }
                        } else {
                            Thread.sleep(getRandomDelay());
                        }
