public class DeadlockAvoidanceMechanism {
    private static final int MAX_RETRIES = 5;
    private static final long DELAY_MS = 100;

    public static void main(String[] args) {
        Container originContainer = new Container();
        Container targetContainer = new Container();

        // Swap elements between containers
        try {
            swapElements(originContainer, targetContainer, 5);
        } catch (InsufficientElementsException e) {
            System.out.println("Failed to swap elements: " + e.getMessage());
        }
    }

    private static void swapElements(Container originContainer, Container targetContainer, int elementCount) throws InsufficientElementsException {
        // Try to acquire locks on both containers
        for (int i = 0; i < MAX_RETRIES; i++) {
            if (!originContainer.tryLock(DELAY_MS, TimeUnit.MILLISECONDS)) {
                continue;
            }

            try {
                // Check if origin container has enough elements
                if (originContainer.getCount() >= elementCount) {
                    // Try to acquire lock on target container
                    if (!targetContainer.tryLock(DELAY_MS, TimeUnit.MILLISECONDS)) {
                        continue;
                    }

                    try {
                        // Swap elements between containers
                        for (int j = 0; j < elementCount; j++) {
                            originContainer.incrementCount();
                            targetContainer.decrementCount();
                        }
                    } finally {
                        targetContainer.unlock();
                    }
                } else {
                    throw new InsufficientElementsException("Origin container has insufficient elements");
                }
            } finally {
                originContainer.unlock();
            }

            // Successfully swapped elements, return
            return;
        }

        // Failed to acquire locks on both containers after maximum retries
        throw new InsufficientElementsException("Failed to acquire locks on both containers");
    }
