class Container {
    private final ReentrantLock lock = new ReentrantLock();
    private final List<Element> elements = new ArrayList<>();

    public void addElement(Element element) {
        try {
            lock.lock();
            elements.add(element);
        } finally {
            lock.unlock();
        }
    }

    public Element removeElement() {
        try {
            lock.lock();
            return elements.remove(0);
        } finally {
            lock.unlock();
        }
    }
}

class SwapTask implements Runnable {
    private final Container origin;
    private final Container target;

    public SwapTask(Container origin, Container target) {
        this.origin = origin;
        this.target = target;
    }

    @Override
    public void run() {
        try {
            swap();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public boolean swap(int count) throws InterruptedException {
        while (count > 0) {
            Element element = origin.removeElement();
            target.addElement(element);
            count--;
        }

        return true;
    }
}

