import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class Grimoire {
    private final List<Rune> runes = new ArrayList<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(2);

    public void addRune(Rune rune) {
        runes.add(rune);
    }

    public int channelTheGrimoire() throws InterruptedException {
        List<Harmony> harmonies = new ArrayList<>();

        // Transmute the runes using a custom comparator that sequences them first by constellation and then by resonance.
        Collections.sort(runes, (rune1, rune2) -> {
            if (rune1.getConstellation() != rune2.getConstellation()) {
                return rune1.getConstellation().compareTo(rune2.getConstellation());
            } else {
                return rune1.getResonance().compareTo(rune2.getResonance());
            }
        });

        // Weave the runes together for harmonizing.
        List<Rune> weavedRunes = new ArrayList<>();
        int i = 0;
        while (i < runes.size()) {
            Rune currentRune = runes.get(i);
            if (currentRune.isSameConstellation() && !currentRune.isOppositeResonance()) {
                // Start a new harmony.
                Harmony harmony = new Harmony();
                harmony.addRune(currentRune);
                weavedRunes.add(currentRune);
                i++;
            } else if (i < runes.size() - 1) {
                // Weave the next rune with the current one.
                Rune nextRune = runes.get(i + 1);
                harmony.addRune(nextRune);
                weavedRunes.add(currentRune);
                i++;
            } else {
                // End of the list, finish the last harmony.
                Harmony harmony = new Harmony();
                harmony.addRune(currentRune);
                weavedRunes.add(currentRune);
                break;
            }
        }

        // Submit each harmony to the executor service for processing.
        List<Future<Integer>> futures = new ArrayList<>();
        for (Harmony harmony : harmonies) {
            futures.add(executorService.submit(() -> processHarmony(harmony)));
        }

        // Wait for all the tasks to complete and return the total number of valid harmonies.
        int validHarmonies = 0;
        for (Future<Integer> future : futures) {
            validHarmonies += future.get();
        }
        return validHarmonies;
    }

    private int processHarmony(Harmony harmony) {
        // Check if the harmony is valid, and return 1 if it is, or 0 if it's not.
        boolean isValid = true;
        for (Rune rune : harmony.getRunes()) {
            if (!rune.isSameConstellation() || !rune.isOppositeResonance()) {
                isValid = false;
                break;
            }
        }
        return isValid ? 1 : 0;
    }
}

