    public int channelTheGrimoire() {
        // Create a thread pool with at most 2 additional threads beyond the main thread
        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Sequence runes by constellation and then by resonance using a custom comparator
        Collections.sort(this.runes, new Comparator<Rune>() {
            @Override
            public int compare(Rune r1, Rune r2) {
                if (r1.getConstellation() == r2.getConstellation()) {
                    return r1.getResonance().compareTo(r2.getResonance());
                } else {
                    return r1.getConstellation().compareTo(r2.getConstellation());
                }
            }
        });

        // Create a list of harmonies to be filled by threads
        List<Harmony> harmonies = new ArrayList<>();

        // Iterate over pairs of runes and create a thread for each pair that is compatible
        for (int i = 0; i < this.runes.size() - 1; i++) {
            Rune r1 = this.runes.get(i);
            Rune r2 = this.runes.get(i + 1);

