import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.locks.ReentrantLock;

class Hoard {
    private final int id;
    private final ReentrantLock lock = new ReentrantLock();
    private GemAmount gems;

    public Hoard(int id) {
        this.id = id;
    }

    public void transferGems(Hoard other, GemAmount amount) throws InsufficientGemsException {
        // Acquire locks in predictable order to avoid deadlock
        if (this.id < other.id) {
            this.lock.lock();
            try {
                other.lock.lock();
                try {
                    if (this.gems.getAmount() >= amount.getAmount()) {
                        // Perform withdrawal and deposit operations
                        GemAmount withdrawn = this.gems.withdraw(amount);
                        other.gems.deposit(withdrawn);
                    } else {
                        throw new InsufficientGemsException("Insufficient gems in Hoard " + this.id);
                    }
                } finally {
                    other.lock.unlock();
                }
            } finally {
                this.lock.unlock();
            }
        } else {
            other.lock.lock();
            try {
                this.lock.lock();
                try {
                    if (other.gems.getAmount() >= amount.getAmount()) {
                        // Perform withdrawal and deposit operations
                        GemAmount withdrawn = other.gems.withdraw(amount);
                        this.gems.deposit(withdrawn);
                    } else {
                        throw new InsufficientGemsException("Insufficient gems in Hoard " + other.id);
                    }
                } finally {
                    this.lock.unlock();
                }
            } finally {
                other.lock.unlock();
            }
        }
    }
}

class GemAmount {
    private final int amount;

    public GemAmount(int amount) {
        this.amount = amount;
    }

    public int getAmount() {
        return amount;
    }

    public void withdraw(GemAmount other) throws InsufficientGemsException {
        if (this.amount >= other.getAmount()) {
            this.amount -= other.getAmount();
        } else {
            throw new InsufficientGemsException("Insufficient gems in GemAmount");
        }
    }

    public void deposit(GemAmount other) {
        this.amount += other.getAmount();
    }
}

class InsufficientGemsException extends Exception {
    public InsufficientGemsException(String message) {
        super(message);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        // Create two hoards with different IDs
        Hoard hoard1 = new Hoard(1);
        Hoard hoard2 = new Hoard(2);

        // Initialize gems in each hoard
        hoard1.gems = new GemAmount(100);
        hoard2.gems = new GemAmount(50);

        // Create a thread pool with two threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Submit tasks to transfer gems between hoards in parallel
        executor.submit(() -> {
            try {
                hoard1.transferGems(hoard2, new GemAmount(50));
            } catch (InsufficientGemsException e) {
                System.out.println("Error: " + e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                hoard2.transferGems(hoard1, new GemAmount(25));
            } catch (InsufficientGemsException e) {
                System.out.println("Error: " + e.getMessage());
            }
        });

        // Shut down the thread pool and await termination
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
    }
}

