        this.gems = gems;
    }

    public synchronized void transferGems(Hoard other, int amount) {
        if (this.gems >= amount && other.hasSufficientGems(amount)) {
            this.gems -= amount;
            other.gems += amount;
        } else {
            throw new InsufficientGemsException();
        }
    }

    public synchronized boolean hasSufficientGems(int amount) {
