        TransferThread transfer2 = new TransferThread(3, 4, 50);
        executor.submit(transfer1);
        executor.submit(transfer2);
    }

    private static class TransferThread implements Runnable {
        private int fromNode;
        private int toNode;
        private int amount;

        public TransferThread(int fromNode, int toNode, int amount) {
            this.fromNode = fromNode;
            this.toNode = toNode;
            this.amount = amount;
        }

        @Override
        public void run() {
            // Acquire locks for both nodes in a stable order
            VaultNode fromVault = VaultNode.getInstance(fromNode);
            VaultNode toVault = VaultNode.getInstance(toNode);
            synchronized (fromVault) {
                synchronized (toVault) {
                    // Perform the transfer
                    CrystalAmount crystals = fromVault.withdraw(amount);
                    toVault.deposit(crystals);
                }
            }
        }
    }

