import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class SigilLedger {
    private Map<String, String> mysticalRunes;
    private ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public SigilLedger(Map<String, String> runes) {
        this.mysticalRunes = runes;
    }

    // read-write lock charm for thread safety
    private void acquireReadLock() throws InterruptedException {
        lock.readLock().lock();
    }

    private void releaseReadLock() {
        lock.readLock().unlock();
    }

    private void acquireWriteLock() throws InterruptedException {
        lock.writeLock().lock();
    }

    private void releaseWriteLock() {
        lock.writeLock().unlock();
    }

    // methods for read and write operations
    public String get(String key) {
        try {
            acquireReadLock();
            return mysticalRunes.get(key);
        } finally {
            releaseReadLock();
        }
    }

    public int size() {
        try {
            acquireReadLock();
            return mysticalRunes.size();
        } finally {
            releaseReadLock();
        }
    }

    public boolean isEmpty() {
        try {
            acquireReadLock();
            return mysticalRunes.isEmpty();
        } finally {
            releaseReadLock();
        }
    }

    public boolean containsKey(String key) {
        try {
            acquireReadLock();
            return mysticalRunes.containsKey(key);
        } finally {
            releaseReadLock();
        }
    }

    public boolean containsValue(String value) {
        try {
            acquireReadLock();
            return mysticalRunes.containsValue(value);
        } finally {
            releaseReadLock();
        }
    }

    public String put(String key, String value) {
        try {
            acquireWriteLock();
            return mysticalRunes.put(key, value);
        } finally {
            releaseWriteLock();
        }
    }

    public void putAll(Map<String, String> map) {
        try {
            acquireWriteLock();
            mysticalRunes.putAll(map);
        } finally {
            releaseWriteLock();
        }
    }

    public String remove(String key) {
        try {
            acquireWriteLock();
            return mysticalRunes.remove(key);
        } finally {
            releaseWriteLock();
        }
    }

    public void clear() {
        try {
            acquireWriteLock();
            mysticalRunes.clear();
        } finally {
            releaseWriteLock();
        }
    }
}

