import java.util.concurrent.*;

public class MoonlightSandsTimer implements Runnable {
    private boolean flowing;
    private long sandStart, sandEnd;

    public MoonlightSandsTimer() {
        this.flowing = false;
        this.sandStart = 0L;
        this.sandEnd = 0L;
    }

