    public synchronized void run() {
        long currentNanoGrain = System.nanoTime();

        if (!this.flowing) {
            this.flowing = true;
            this.sandStart = currentNanoGrain;
        } else {
            this.sandEnd = currentNanoGrain;
        }
    }

    public synchronized void reset() {
