public class DeadlockAvoidanceMechanism {
    public static void main(String[] args) {
        // Initialize accounts
        Account sourceAccount = new Account("Source", 100);
        Account destinationAccount = new Account("Destination", 50);

        // Initialize thread pool with maximum of 2 threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Transfer money between accounts using deadlock avoidance mechanism
        try {
            transferMoney(sourceAccount, destinationAccount, 10, Duration.ofSeconds(5), executor);
        } catch (InsufficientFundsException e) {
            System.out.println("Insufficient funds: " + e.getMessage());
        } finally {
            // Shutdown thread pool
            executor.shutdown();
        }
    }

    private static void transferMoney(Account sourceAccount, Account destinationAccount, int amount, Duration timeout, ExecutorService executor) throws InsufficientFundsException {
        // Create a reentrant lock for each account
        ReentrantLock sourceLock = new ReentrantLock();
        ReentrantLock destinationLock = new ReentrantLock();

        // Acquire locks on both accounts using tryLock with timeout and random backoff strategy
        if (!acquireLocks(sourceAccount, destinationAccount, amount, timeout, executor)) {
            throw new InsufficientFundsException("Timeout while acquiring locks");
        }

        // Transfer money between accounts
        sourceAccount.withdraw(amount);
        destinationAccount.deposit(amount);
    }

    private static boolean acquireLocks(Account sourceAccount, Account destinationAccount, int amount, Duration timeout, ExecutorService executor) {
        long startTime = System.currentTimeMillis();
        long currentTime;
        long waitTime;
        Random random = new Random();

        while (true) {
            // Acquire lock on source account
            if (!sourceAccount.lock.tryLock()) {
                return false;
            }

            // Acquire lock on destination account
            if (!destinationAccount.lock.tryLock()) {
                return false;
            }

            // Check if the transfer can be made
            if (amount <= sourceAccount.balance) {
                return true;
            } else {
                // Release locks and retry after random delay
                sourceAccount.lock.unlock();
                destinationAccount.lock.unlock();

                waitTime = getWaitTime(random, currentTime - startTime);
                if (waitTime > timeout.toMillis()) {
