            Account destinationAccount = new Account();
            DollarAmount amountToTransfer = new DollarAmount(100);

            // Start the transfer task
            Future<Boolean> future = executor.submit(() -> transfer(sourceAccount, destinationAccount, amountToTransfer));

            // Wait for the result with a timeout
            try {
                Boolean result = future.get(TIMEOUT_DURATION, TIMEOUT_UNIT);
                System.out.println("Result: " + result);
            } catch (TimeoutException e) {
                System.err.println("Transfer timed out");
            } finally {
                executor.shutdown();
            }
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions appropriately
        }
    }

    private static Boolean transfer(Account sourceAccount, Account destinationAccount, DollarAmount amountToTransfer) throws InterruptedException {
        Lock sourceLock = new ReentrantLock();
        Lock destinationLock = new ReentrantLock();

        try {
            // Acquire locks with a timeout and random backoff strategy
            if (!acquireLocks(sourceLock, destinationLock)) {
                return false;
            }

            // Check that the source account has sufficient funds
            if (amountToTransfer.getAmount() > sourceAccount.getBalance()) {
                throw new InsufficientFundsException();
            }

            // Perform the transfer
            System.out.println("Transferring " + amountToTransfer.getAmount() + " from " + sourceAccount.getName() + " to " + destinationAccount.getName());
            sourceAccount.debit(amountToTransfer);
            destinationAccount.credit(amountToTransfer);

            return true;
        } finally {
            // Release the locks in a finally block to ensure they are always released, even if an exception is thrown
            releaseLocks(sourceLock, destinationLock);
        }
    }

    private static boolean acquireLocks(Lock sourceLock, Lock destinationLock) throws InterruptedException {
        int numAttempts = 0;
        long delayMillis = calculateFixedDelay(numAttempts++);

        // Try to acquire the locks with a timeout and random backoff strategy
        while (true) {
            if (sourceLock.tryLock(delayMillis, TimeUnit.MILLISECONDS)) {
                try {
                    if (destinationLock.tryLock(delayMillis, TimeUnit.MILLISECONDS)) {
                        return true;
                    }
                } finally {
                    sourceLock.unlock();
                }
            }

            // Increment the delay and try again
            delayMillis = calculateFixedDelay(numAttempts++);
        }
    }

    private static long calculateFixedDelay(int numAttempts) {
        return (long) (Math.pow(2, numAttempts) * Math.random());
    }

    private static void releaseLocks(Lock sourceLock, Lock destinationLock) {
        // Release the locks in a finally block to ensure they are always released, even if an exception is thrown
        try {
            sourceLock.unlock();
            destinationLock.unlock();
        } catch (IllegalMonitorStateException e) {
            // Ignore
        }
    }
}

