    }

    public Object take() throws InterruptedException {
        availableItems.acquire(); // Blocks until an item is available in the buffer
        synchronized (buffer) {
            Object x = buffer[head];
            head = (head + 1) % CAPACITY;
            return x;
        }
    }

    public boolean isEmpty() {
        return tail == head; // Checks if the buffer is empty
    }

    public boolean isFull() {
        return ((tail + 1) % CAPACITY) == head; // Checks if the buffer is full
    }
