import java.util.concurrent.atomic.AtomicReference;

public class ConcurrentStack<T> {
    private static class Node<T> {
        T item;
        AtomicReference<Node<T>> next = new AtomicReference<>();

        public Node(T item) {
            this.item = item;
        }
    }

    private final AtomicReference<Node<T>> top = new AtomicReference<>();

    public void push(T item) {
        Node<T> node = new Node<>(item);
        for (;;) {
            Node<T> currentTop = top.get();
            node.next.set(currentTop);
            if (top.compareAndSet(currentTop, node)) {
                return;
            }
        }
    }

    public T pop() {
        for (;;) {
            Node<T> currentTop = top.get();
            if (currentTop == null) {
                return null;
            }
            if (top.compareAndSet(currentTop, currentTop.next.get())) {
                return currentTop.item;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack<Integer> stack = new ConcurrentStack<>();
        int numThreads = 4;
        Thread[] threads = new Thread[numThreads];
        for (int i = 0; i < numThreads; i++) {
            threads[i] = new Thread(new Runnable() {
