        for (Thread thread : threads) {
            thread.start();
        }
        for (Thread thread : threads) {
            thread.join();
        }
        System.out.println("ConcurrentStack test complete.");
    }
}

import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TreiberStack {
    private static AtomicReference<Node> top = new AtomicReference<>();

    public static void push(int value) {
        Node node = new Node(value);
        while (true) {
            Node currentTop = top.get();
            if (top.compareAndSet(currentTop, node)) {
                return;
            }
        }
    }

    public static int pop() {
        while (true) {
            Node currentTop = top.get();
            if (currentTop == null) {
                return -1;
            }
            Node next = currentTop.next;
            if (top.compareAndSet(currentTop, next)) {
                return currentTop.value;
            }
        }
    }
}

public class Main {
