            System.out.println("All tasks finished successfully.");
        } else {
            System.out.println("Timeout while waiting for tasks to finish.");
        }
    }
}

import java.util.concurrent.atomic.AtomicReference;

public class ConcurrentStack {
    private static class Node {
        public final int item;
        public Node next;

        public Node(int item) {
            this.item = item;
        }
    }

    private AtomicReference<Node> top = new AtomicReference<>();

    public void push(int item) {
        Node newNode = new Node(item);
        Node currentTop = top.get();
        do {
            newNode.next = currentTop;
        } while (!top.compareAndSet(currentTop, newNode));
    }

    public int pop() {
        Node currentTop = top.get();
        if (currentTop == null) return -1;
        do {
            currentTop = currentTop.next;
        } while (!top.compareAndSet(currentTop, currentTop.next));
        return currentTop.item;
    }
}

public static void main(String[] args) throws InterruptedException {
