import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class AnimalLoader {
    private static final int MAX_THREADS = 3; // maximum number of threads to use

    public static void main(String[] args) throws InterruptedException {
        List<Animal> candidates = new ArrayList<>();
        // initialize the list of candidate animals
        candidates.add(new Animal("Lion", "Male"));
        candidates.add(new Animal("Lion", "Female"));
        candidates.add(new Animal("Tiger", "Male"));
        candidates.add(new Animal("Tiger", "Female"));
        candidates.add(new Animal("Bear", "Male"));
        candidates.add(new Animal("Bear", "Female"));

        // create a fixed thread pool with MAX_THREADS threads
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        // submit the loadTheArk task to the executor service
        Future<Integer> result = executor.submit(() -> loadTheArk(candidates));

        System.out.println("Number of valid pairs: " + result.get());
    }

    private static int loadTheArk(List<Animal> candidates) {
        // sort the candidate animals by species and gender using a custom comparator
        Comparator<Animal> animalComparator = new AnimalComparator();
        Collections.sort(candidates, animalComparator);

        int validPairs = 0;
        for (int i = 0; i < candidates.size() - 1; i++) {
            // check if the current animal and its next animal are a valid pair
            Animal currentAnimal = candidates.get(i);
            Animal nextAnimal = candidates.get(i + 1);
            if (isValidPair(currentAnimal, nextAnimal)) {
                validPairs++;
            }
        }
        return validPairs;
    }

    private static boolean isValidPair(Animal animal1, Animal animal2) {
        // check if the animals are of the same species and have opposite genders
        if (animal1.getSpecies().equals(animal2.getSpecies()) && !animal1.getGender().equals(animal2.getGender())) {
            return true;
        } else {
            return false;
        }
    }
}

