        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Create a list of candidate animals
        List<Animal> candidates = new ArrayList<>();
        candidates.add(new Animal("Lion", "Male"));
        candidates.add(new Animal("Tiger", "Female"));
        candidates.add(new Animal("Zebra", "Male"));
        candidates.add(new Animal("Giraffe", "Female"));

        // Sort the candidate animals by species and gender
        executor.execute(() -> {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }

            Collections.sort(candidates, new Comparator<Animal>() {
                @Override
                public int compare(Animal a, Animal b) {
                    if (!a.getSpecies().equals(b.getSpecies())) {
                        return a.getSpecies().compareTo(b.getSpecies());
                    } else {
                        if (a.isMale() && !b.isFemale()) {
                            return -1;
                        } else if (!a.isMale() && b.isFemale()) {
                            return 1;
                        } else {
                            return 0;
                        }
                    }
                }
            });

            System.out.println("Sorted animals: " + candidates);
        });

        // Load the ark with pairs of animals
        executor.execute(() -> {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }

            int count = 0;
            for (int i = 0; i < candidates.size() - 1; i += 2) {
                if (!candidates.get(i).isMale() && !candidates.get(i + 1).isFemale()) {
                    System.out.println("Loaded pair: " + candidates.get(i) + ", " + candidates.get(i + 1));
                    count++;
                } else {
                    System.out.println("Incompatible pair: " + candidates.get(i) + ", " + candidates.get(i + 1));
                }
            }

            System.out.println("Total pairs loaded: " + count);
        });

        // Shutdown the executor service
        executor.shutdown();
    }
}

