        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable producer = () -> {
            int numPrimes = 10; // The number of primes to generate
            for (int i = 0; i < numPrimes; i++) {
                try {
                    queue.put(generatePrime());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        Runnable consumer = () -> {
            while (!queue.isEmpty()) {
                try {
                    System.out.println(queue.take());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        executor.submit(producer);
        executor.submit(consumer);

        // Shut down the executor when both producer and consumer are finished
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.DAYS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            executor.shutdownNow();
        }
    }

    private static int generatePrime() {
        // Generate a random number between 2 and 100
        int num = (int) (Math.random() * 98 + 2);
        for (int i = 2; i < Math.sqrt(num); i++) {
            if (num % i == 0) return 0; // Not a prime
        }
        return num; // Prime found
    }
