import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class ConcurrentProcessing {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        // Create a list of elements to process
        List<Element> elements = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            Element element = new Element();
            element.setId(i);
            element.setData("Element " + i);
            elements.add(element);
        }

        // Create a thread pool with 2 threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Submit the sequential processing task
        Future<List<Result>> sequentialResultsFuture = executor.submit(() -> {
            return processElementsSequentially(elements);
        });

        // Submit the parallel processing task
        Future<List<Result>> parallelResultsFuture = executor.submit(() -> {
            return processElementsParallel(elements, executor);
        });

        // Wait for both tasks to complete
        List<Result> sequentialResults = sequentialResultsFuture.get();
        List<Result> parallelResults = parallelResultsFuture.get();

        // Print the results
        System.out.println("Sequential processing results:");
        printResults(sequentialResults);

        System.out.println("Parallel processing results:");
        printResults(parallelResults);
    }

    private static List<Result> processElementsSequentially(List<Element> elements) {
        // Create a list to store the results
        List<Result> results = new ArrayList<>();

        // Process each element sequentially
        for (Element element : elements) {
            Result result = processElement(element);
            results.add(result);
        }

        return results;
    }

    private static List<Result> processElementsParallel(List<Element> elements, ExecutorService executor) throws InterruptedException, ExecutionException {
        // Create a list to store the results
        List<Result> results = new ArrayList<>();

        // Submit each element for parallel processing
        List<Future<Result>> futures = new ArrayList<>();
        for (Element element : elements) {
            Future<Result> future = executor.submit(() -> {
                return processElement(element);
            });
            futures.add(future);
        }

        // Wait for all tasks to complete
        for (Future<Result> future : futures) {
            results.add(future.get());
        }

        return results;
    }

    private static Result processElement(Element element) {
        // Perform some computation on the element
        String data = element.getData();
        int length = data.length();
        long sum = 0;
        for (int i = 0; i < length; i++) {
            char ch = data.charAt(i);
            sum += ch;
        }

        // Return the result
        return new Result(element, sum);
    }

    private static void printResults(List<Result> results) {
        for (Result result : results) {
            System.out.println(result.getId() + ": " + result.getData());
        }
    }
}

